fn main() {
    let list = [7, 4, 9, 10];
    let mut sum_even = 0;

    for &x in &list {
        if x % 2 == 0 {
            sum_even += x;
        } else {
            println!("{}", x * 2);
        }
    }

    println!("Total of even entries: {}", sum_even);
}

